// SearchVideosMatchingCompilerVideo is the manifest mock matchingCompilerVideo: The search for compiler on channel UC1234567890123456789012 returns three pages with video AbCdEfGhI12 repeated across a boundary.
func SearchVideosMatchingCompilerVideo() connectormock.Case[youtube.VideoSearchPage] {
	pages := []youtube.VideoSearchPage{
		connectormock.MustDecodeOutput[youtube.VideoSearchPage](`{"results":[{"videoId":"AbCdEfGhI12","channelId":"UC1234567890123456789012","channelTitle":"Compiler Lab","title":"Compiler release walkthrough","description":"A short compiler tour","publishedAt":"2026-10-20T10:00:00Z"}],"nextPageToken":"compiler-search-2","totalResults":2}`),
		connectormock.MustDecodeOutput[youtube.VideoSearchPage](`{"results":[{"videoId":"AbCdEfGhI12","channelId":"UC1234567890123456789012","channelTitle":"Compiler Lab","title":"Compiler release walkthrough","description":"A short compiler tour","publishedAt":"2026-10-20T10:00:00Z"},{"videoId":"ZxCvBnMaS34","channelId":"UC1234567890123456789012","channelTitle":"Compiler Lab","title":"Compiler setup tips","description":"A setup guide","publishedAt":"2026-10-10T10:00:00Z"}],"nextPageToken":"compiler-search-3","totalResults":2}`),
		connectormock.MustDecodeOutput[youtube.VideoSearchPage](`{"results":[],"totalResults":2}`),
	}
	pageNumber := connectormock.CursorPageNumber[youtube.SearchVideosInput]("pageToken", "nextPageToken", pages)
	return connectormock.Paged(youtube.SearchVideosBranchSearched, pageNumber, pages...)
}

